`timescale 1ns / 1ps
// !!!AI-GENERATED!!!
//======================================================================
// Testbench: tb_NTT_Acc_Control_Top
//
// Purpose:
//
//   Integration test for:
//
//       NTT_AXIL_Regs
//              +
//       Acc_Controller
//
//----------------------------------------------------------------------
// Unlike the previous unit tests:
//
//   We DO NOT directly drive:
//
//       Start_pulse
//       Busy
//       Done
//
//   Instead:
//
//       START is generated through a real AXI4-Lite write.
//
//       BUSY / DONE are generated by Acc_Controller.
//
//       Software-visible status is checked through a real AXI4-Lite read.
//
//----------------------------------------------------------------------
// Overall test path:
//
//   AXI Write SRC_ADDR
//          |
//          v
//   AXI Write DST_ADDR
//          |
//          v
//   AXI Write CONTROL.START
//          |
//          v
//   NTT_AXIL_Regs
//          |
//          | Start_pulse
//          v
//   Acc_Controller
//          |
//          | Load_start
//          v
//   Fake input loader
//          |
//          | Load_done
//          v
//   Acc_Controller
//          |
//          | Core_start
//          v
//   Fake NTT core
//          |
//          | Core_fin
//          v
//   Acc_Controller
//          |
//          | Write_start
//          v
//   Fake output writer
//          |
//          | Write_done
//          v
//   Acc_Controller
//          |
//          | Done
//          v
//   NTT_AXIL_Regs STATUS
//          |
//          v
//   AXI Read STATUS
//
//======================================================================

module tb_NTT_Acc_Control_Top;


    //==================================================================
    // Register Address Map
    //==================================================================

    localparam [31:0] ADDR_CONTROL  = 32'h0000_0000;
    localparam [31:0] ADDR_STATUS   = 32'h0000_0004;
    localparam [31:0] ADDR_SRC_ADDR = 32'h0000_0008;
    localparam [31:0] ADDR_DST_ADDR = 32'h0000_000C;


    //==================================================================
    // Clock / Reset
    //==================================================================

    reg ACLK;
    reg ARESETn;


    //==================================================================
    // AXI4-Lite Write Address Channel
    //==================================================================

    reg  [31:0] S_AXI_AWADDR;
    reg         S_AXI_AWVALID;
    wire        S_AXI_AWREADY;


    //==================================================================
    // AXI4-Lite Write Data Channel
    //==================================================================

    reg  [31:0] S_AXI_WDATA;
    reg  [3:0]  S_AXI_WSTRB;
    reg         S_AXI_WVALID;
    wire        S_AXI_WREADY;


    //==================================================================
    // AXI4-Lite Write Response Channel
    //==================================================================

    wire [1:0] S_AXI_BRESP;
    wire       S_AXI_BVALID;
    reg        S_AXI_BREADY;


    //==================================================================
    // AXI4-Lite Read Address Channel
    //==================================================================

    reg  [31:0] S_AXI_ARADDR;
    reg         S_AXI_ARVALID;
    wire        S_AXI_ARREADY;


    //==================================================================
    // AXI4-Lite Read Data Channel
    //==================================================================

    wire [31:0] S_AXI_RDATA;
    wire [1:0]  S_AXI_RRESP;
    wire        S_AXI_RVALID;
    reg         S_AXI_RREADY;


    //==================================================================
    // Interfaces to future blocks
    //
    // In this TB these are controlled manually.
    //
    // Later:
    //
    //   Load_done  <- AXI4 Input Loader
    //   Core_fin   <- Thesis NTT/INTT Core
    //   Write_done <- AXI4 Output Writer
    //
    //==================================================================

    wire Load_start;
    reg  Load_done;

    wire Core_start;
    reg  Core_fin;

    wire Write_start;
    reg  Write_done;


    //==================================================================
    // Latched transaction configuration
    //==================================================================

    wire        Mode_latched;
    wire [31:0] Src_addr_latched;
    wire [31:0] Dst_addr_latched;


    //==================================================================
    // Accelerator Status
    //==================================================================

    wire Busy;
    wire Done;
    wire Error;


    //==================================================================
    // Testbench variables
    //==================================================================

    integer test_count;
    integer error_count;

    reg [31:0] read_value;


    //==================================================================
    // DUT
    //==================================================================

    NTT_Acc_Control_Top DUT (

        .ACLK              (ACLK),
        .ARESETn           (ARESETn),

        // AXI AW
        .S_AXI_AWADDR      (S_AXI_AWADDR),
        .S_AXI_AWVALID     (S_AXI_AWVALID),
        .S_AXI_AWREADY     (S_AXI_AWREADY),

        // AXI W
        .S_AXI_WDATA       (S_AXI_WDATA),
        .S_AXI_WSTRB       (S_AXI_WSTRB),
        .S_AXI_WVALID      (S_AXI_WVALID),
        .S_AXI_WREADY      (S_AXI_WREADY),

        // AXI B
        .S_AXI_BRESP       (S_AXI_BRESP),
        .S_AXI_BVALID      (S_AXI_BVALID),
        .S_AXI_BREADY      (S_AXI_BREADY),

        // AXI AR
        .S_AXI_ARADDR      (S_AXI_ARADDR),
        .S_AXI_ARVALID     (S_AXI_ARVALID),
        .S_AXI_ARREADY     (S_AXI_ARREADY),

        // AXI R
        .S_AXI_RDATA       (S_AXI_RDATA),
        .S_AXI_RRESP       (S_AXI_RRESP),
        .S_AXI_RVALID      (S_AXI_RVALID),
        .S_AXI_RREADY      (S_AXI_RREADY),

        // Input loader
        .Load_start        (Load_start),
        .Load_done         (Load_done),

        // Core
        .Core_start        (Core_start),
        .Core_fin          (Core_fin),

        // Writer
        .Write_start       (Write_start),
        .Write_done        (Write_done),

        // Latched configuration
        .Mode_latched      (Mode_latched),
        .Src_addr_latched  (Src_addr_latched),
        .Dst_addr_latched  (Dst_addr_latched),

        // Status
        .Busy              (Busy),
        .Done              (Done),
        .Error             (Error)
    );


    //==================================================================
    // Clock
    //
    // Period = 10 ns
    // Frequency = 100 MHz
    //==================================================================

    initial begin

        ACLK = 1'b0;

        forever begin
            #5 ACLK = ~ACLK;
        end

    end


    //==================================================================
    // Waveform
    //==================================================================

    initial begin

        $dumpfile("NTT_Acc_Control_Top_tb.vcd");
        $dumpvars(0, tb_NTT_Acc_Control_Top);

    end


    //==================================================================
    // CHECK_1
    //==================================================================

    task CHECK_1;

        input Actual;
        input Expected;
        input [8*64-1:0] Name;

        begin

            test_count = test_count + 1;

            if(Actual !== Expected) begin

                error_count = error_count + 1;

                $display(
                    "[FAIL] %0s : Expected = %b, Actual = %b",
                    Name,
                    Expected,
                    Actual
                );

            end
            else begin

                $display(
                    "[PASS] %0s : %b",
                    Name,
                    Actual
                );

            end

        end

    endtask


    //==================================================================
    // CHECK_32
    //==================================================================

    task CHECK_32;

        input [31:0] Actual;
        input [31:0] Expected;
        input [8*64-1:0] Name;

        begin

            test_count = test_count + 1;

            if(Actual !== Expected) begin

                error_count = error_count + 1;

                $display(
                    "[FAIL] %0s : Expected = 0x%08H, Actual = 0x%08H",
                    Name,
                    Expected,
                    Actual
                );

            end
            else begin

                $display(
                    "[PASS] %0s : 0x%08H",
                    Name,
                    Actual
                );

            end

        end

    endtask


    //==================================================================
    // RESET_DUT
    //==================================================================

    task RESET_DUT;

        begin

            //----------------------------------------------------------
            // AXI Write Master -> idle
            //----------------------------------------------------------

            S_AXI_AWADDR  = 32'b0;
            S_AXI_AWVALID = 1'b0;

            S_AXI_WDATA   = 32'b0;
            S_AXI_WSTRB   = 4'b0;
            S_AXI_WVALID  = 1'b0;

            S_AXI_BREADY  = 1'b0;


            //----------------------------------------------------------
            // AXI Read Master -> idle
            //----------------------------------------------------------

            S_AXI_ARADDR  = 32'b0;
            S_AXI_ARVALID = 1'b0;

            S_AXI_RREADY  = 1'b0;


            //----------------------------------------------------------
            // Future block completion signals -> idle
            //----------------------------------------------------------

            Load_done  = 1'b0;
            Core_fin   = 1'b0;
            Write_done = 1'b0;


            //----------------------------------------------------------
            // Assert reset
            //----------------------------------------------------------

            ARESETn = 1'b0;

            repeat(2)
                @(posedge ACLK);


            //----------------------------------------------------------
            // Release reset away from active clock edge
            //----------------------------------------------------------

            @(negedge ACLK);

            ARESETn = 1'b1;

            @(posedge ACLK);

            #1;

        end

    endtask


    //==================================================================
    // SEND_AW
    //
    // Send only AXI Write Address channel.
    //==================================================================

    task automatic SEND_AW;

        input [31:0] Address;

        begin

            @(negedge ACLK);

            S_AXI_AWADDR  = Address;
            S_AXI_AWVALID = 1'b1;


            //----------------------------------------------------------
            // Handshake:
            //
            //      AWVALID && AWREADY
            //----------------------------------------------------------

            @(posedge ACLK);

            while(S_AXI_AWREADY !== 1'b1)
                @(posedge ACLK);


            //----------------------------------------------------------
            // Address accepted.
            //----------------------------------------------------------

            @(negedge ACLK);

            S_AXI_AWVALID = 1'b0;

        end

    endtask


    //==================================================================
    // SEND_W
    //==================================================================

    task automatic SEND_W;

        input [31:0] Data;
        input [3:0]  Wstrb;

        begin

            @(negedge ACLK);

            S_AXI_WDATA  = Data;
            S_AXI_WSTRB  = Wstrb;
            S_AXI_WVALID = 1'b1;


            //----------------------------------------------------------
            // Handshake:
            //
            //      WVALID && WREADY
            //----------------------------------------------------------

            @(posedge ACLK);

            while(S_AXI_WREADY !== 1'b1)
                @(posedge ACLK);


            @(negedge ACLK);

            S_AXI_WVALID = 1'b0;

        end

    endtask


    //==================================================================
    // AXI_WRITE
    //
    // Complete one AXI4-Lite Write transaction.
    //==================================================================

    task automatic AXI_WRITE;

        input [31:0] Address;
        input [31:0] Data;

        begin

            //----------------------------------------------------------
            // AW and W are independent AXI channels.
            //
            // Run both in parallel.
            //----------------------------------------------------------

            fork

                SEND_AW(Address);

                SEND_W(
                    Data,
                    4'b1111
                );

            join


            //----------------------------------------------------------
            // Wait for write response.
            //----------------------------------------------------------

            wait(S_AXI_BVALID === 1'b1);

            #1;


            if(S_AXI_BRESP !== 2'b00) begin

                error_count = error_count + 1;

                $display(
                    "[FAIL] AXI WRITE BRESP = %b",
                    S_AXI_BRESP
                );

            end


            //----------------------------------------------------------
            // Accept B response.
            //----------------------------------------------------------

            @(negedge ACLK);

            S_AXI_BREADY = 1'b1;

            @(posedge ACLK);

            #1;


            if(S_AXI_BVALID !== 1'b0) begin

                error_count = error_count + 1;

                $display(
                    "[FAIL] BVALID did not clear"
                );

            end


            @(negedge ACLK);

            S_AXI_BREADY = 1'b0;

        end

    endtask


    //==================================================================
    // AXI_READ
    //
    // Complete one AXI4-Lite Read transaction.
    //==================================================================

    task automatic AXI_READ;

        input  [31:0] Address;
        output [31:0] Data;

        begin

            //----------------------------------------------------------
            // Send AR
            //----------------------------------------------------------

            @(negedge ACLK);

            S_AXI_ARADDR  = Address;
            S_AXI_ARVALID = 1'b1;


            //----------------------------------------------------------
            // Wait AR handshake
            //----------------------------------------------------------

            @(posedge ACLK);

            while(S_AXI_ARREADY !== 1'b1)
                @(posedge ACLK);


            @(negedge ACLK);

            S_AXI_ARVALID = 1'b0;


            //----------------------------------------------------------
            // Wait for read data
            //----------------------------------------------------------

            wait(S_AXI_RVALID === 1'b1);

            #1;


            //----------------------------------------------------------
            // Capture the data BEFORE accepting it.
            //----------------------------------------------------------

            Data = S_AXI_RDATA;


            if(S_AXI_RRESP !== 2'b00) begin

                error_count = error_count + 1;

                $display(
                    "[FAIL] AXI READ RRESP = %b",
                    S_AXI_RRESP
                );

            end


            //----------------------------------------------------------
            // Accept R response
            //----------------------------------------------------------

            @(negedge ACLK);

            S_AXI_RREADY = 1'b1;

            @(posedge ACLK);

            #1;


            if(S_AXI_RVALID !== 1'b0) begin

                error_count = error_count + 1;

                $display(
                    "[FAIL] RVALID did not clear"
                );

            end


            @(negedge ACLK);

            S_AXI_RREADY = 1'b0;

        end

    endtask


    //==================================================================
    // MAIN TEST
    //==================================================================

    initial begin


        //==============================================================
        // Initialization
        //==============================================================

        test_count  = 0;
        error_count = 0;

        ARESETn = 1'b0;

        S_AXI_AWADDR  = 32'b0;
        S_AXI_AWVALID = 1'b0;

        S_AXI_WDATA   = 32'b0;
        S_AXI_WSTRB   = 4'b0;
        S_AXI_WVALID  = 1'b0;

        S_AXI_BREADY  = 1'b0;

        S_AXI_ARADDR  = 32'b0;
        S_AXI_ARVALID = 1'b0;

        S_AXI_RREADY  = 1'b0;

        Load_done  = 1'b0;
        Core_fin   = 1'b0;
        Write_done = 1'b0;


        //==============================================================
        // TEST 1: RESET
        //==============================================================

        $display("");
        $display("================================================");
        $display("TEST 1: RESET");
        $display("================================================");

        RESET_DUT();


        CHECK_1(
            Busy,
            1'b0,
            "Reset Busy"
        );

        CHECK_1(
            Done,
            1'b0,
            "Reset Done"
        );

        CHECK_1(
            Error,
            1'b0,
            "Reset Error"
        );


        //==============================================================
        // TEST 2: PROGRAM SOURCE ADDRESS THROUGH AXI
        //==============================================================

        $display("");
        $display("================================================");
        $display("TEST 2: PROGRAM SRC_ADDR");
        $display("================================================");


        AXI_WRITE(
            ADDR_SRC_ADDR,
            32'h1000_1000
        );


        //--------------------------------------------------------------
        // Read it back through AXI.
        //--------------------------------------------------------------

        AXI_READ(
            ADDR_SRC_ADDR,
            read_value
        );


        CHECK_32(
            read_value,
            32'h1000_1000,
            "SRC_ADDR readback"
        );


        //==============================================================
        // TEST 3: PROGRAM DESTINATION ADDRESS
        //==============================================================

        $display("");
        $display("================================================");
        $display("TEST 3: PROGRAM DST_ADDR");
        $display("================================================");


        AXI_WRITE(
            ADDR_DST_ADDR,
            32'h1000_2000
        );


        AXI_READ(
            ADDR_DST_ADDR,
            read_value
        );


        CHECK_32(
            read_value,
            32'h1000_2000,
            "DST_ADDR readback"
        );


        //==============================================================
        // TEST 4: START ACCELERATOR THROUGH AXI
        //==============================================================

        $display("");
        $display("================================================");
        $display("TEST 4: AXI CONTROL.START");
        $display("================================================");


        //--------------------------------------------------------------
        // CONTROL:
        //
        //      bit 0 = START = 1
        //      bit 1 = MODE  = 1
        //
        // Therefore:
        //
        //      CONTROL = 0x3
        //--------------------------------------------------------------

        AXI_WRITE(
            ADDR_CONTROL,
            32'h0000_0003
        );


        //--------------------------------------------------------------
        // Important:
        //
        // We did NOT directly drive Start_pulse.
        //
        // AXI write -> register block -> Start_pulse -> controller.
        //--------------------------------------------------------------

        CHECK_1(
            Busy,
            1'b1,
            "Controller became busy through AXI START"
        );


        CHECK_1(
            Load_start,
            1'b1,
            "AXI START generated Load_start"
        );


        CHECK_1(
            Mode_latched,
            1'b1,
            "MODE latched through AXI"
        );


        CHECK_32(
            Src_addr_latched,
            32'h1000_1000,
            "SRC_ADDR latched through AXI"
        );


        CHECK_32(
            Dst_addr_latched,
            32'h1000_2000,
            "DST_ADDR latched through AXI"
        );


        //==============================================================
        // TEST 5: SOFTWARE READS BUSY STATUS
        //==============================================================

        $display("");
        $display("================================================");
        $display("TEST 5: READ BUSY STATUS THROUGH AXI");
        $display("================================================");


        //--------------------------------------------------------------
        // STATUS:
        //
        // bit 2 Error = 0
        // bit 1 Done  = 0
        // bit 0 Busy  = 1
        //
        // Therefore:
        //
        //      STATUS = 0x00000001
        //--------------------------------------------------------------

        AXI_READ(
            ADDR_STATUS,
            read_value
        );


        CHECK_32(
            read_value,
            32'h0000_0001,
            "Software sees BUSY through STATUS"
        );


        //==============================================================
        // TEST 6: MODIFY REGISTERS WHILE ACCELERATOR IS BUSY
        //==============================================================

        $display("");
        $display("================================================");
        $display("TEST 6: CONFIGURATION SNAPSHOT INTEGRATION");
        $display("================================================");


        //--------------------------------------------------------------
        // CPU changes SRC/DST while current transaction is running.
        //--------------------------------------------------------------

        AXI_WRITE(
            ADDR_SRC_ADDR,
            32'hDEAD_BEEF
        );


        AXI_WRITE(
            ADDR_DST_ADDR,
            32'hCAFE_BABE
        );


        //--------------------------------------------------------------
        // Also issue another START while Busy.
        //
        // CONTROL:
        //
        //      bit 0 START = 1
        //      bit 1 MODE  = 0
        //
        // This changes the raw Mode register to 0 and generates another
        // Start_pulse.
        //
        // But Acc_Controller is not in IDLE, so the command must NOT
        // replace the current transaction.
        //--------------------------------------------------------------

        AXI_WRITE(
            ADDR_CONTROL,
            32'h0000_0001
        );


        //--------------------------------------------------------------
        // AXI-visible registers HAVE changed.
        //--------------------------------------------------------------

        AXI_READ(
            ADDR_SRC_ADDR,
            read_value
        );


        CHECK_32(
            read_value,
            32'hDEAD_BEEF,
            "CPU-visible SRC_ADDR changed"
        );


        AXI_READ(
            ADDR_DST_ADDR,
            read_value
        );


        CHECK_32(
            read_value,
            32'hCAFE_BABE,
            "CPU-visible DST_ADDR changed"
        );


        //--------------------------------------------------------------
        // But CURRENT accelerator transaction must remain unchanged.
        //--------------------------------------------------------------

        CHECK_1(
            Mode_latched,
            1'b1,
            "Busy START does not change latched Mode"
        );


        CHECK_32(
            Src_addr_latched,
            32'h1000_1000,
            "Busy AXI write does not change current source"
        );


        CHECK_32(
            Dst_addr_latched,
            32'h1000_2000,
            "Busy AXI write does not change current destination"
        );


        CHECK_1(
            Load_start,
            1'b0,
            "START while Busy does not restart loader"
        );


        //==============================================================
        // TEST 7: FAKE INPUT LOADER COMPLETES
        //==============================================================

        $display("");
        $display("================================================");
        $display("TEST 7: INPUT LOAD COMPLETION");
        $display("================================================");


        //--------------------------------------------------------------
        // Pretend AXI4 Input Loader spends several cycles fetching
        // coefficients from memory.
        //--------------------------------------------------------------

        repeat(5)
            @(posedge ACLK);


        //--------------------------------------------------------------
        // Generate Load_done pulse.
        //--------------------------------------------------------------

        @(negedge ACLK);

        Load_done = 1'b1;

        @(posedge ACLK);

        #1;


        //--------------------------------------------------------------
        // Controller should only enter PREP_CORE here.
        //
        // Core_start should NOT appear in the same cycle.
        //--------------------------------------------------------------

        CHECK_1(
            Core_start,
            1'b0,
            "Core does not start immediately on Load_done"
        );


        @(negedge ACLK);

        Load_done = 1'b0;


        //--------------------------------------------------------------
        // Next clock executes PREP_CORE.
        //--------------------------------------------------------------

        @(posedge ACLK);

        #1;


        CHECK_1(
            Core_start,
            1'b1,
            "Core_start generated after input preparation"
        );


        //--------------------------------------------------------------
        // Core_start must be one cycle.
        //--------------------------------------------------------------

        @(posedge ACLK);

        #1;


        CHECK_1(
            Core_start,
            1'b0,
            "Core_start is one-cycle pulse"
        );


        //==============================================================
        // TEST 8: FAKE NTT CORE FINISHES
        //==============================================================

        $display("");
        $display("================================================");
        $display("TEST 8: NTT CORE COMPLETION");
        $display("================================================");


        //--------------------------------------------------------------
        // Pretend NTT core computes for 8 cycles.
        //--------------------------------------------------------------

        repeat(8)
            @(posedge ACLK);


        //--------------------------------------------------------------
        // Core_fin corresponds to the thesis core Fin output.
        //--------------------------------------------------------------

        @(negedge ACLK);

        Core_fin = 1'b1;


        @(posedge ACLK);

        #1;


        //--------------------------------------------------------------
        // Controller enters PREP_WRITE first.
        //
        // The final four NTT coefficients were just produced/captured.
        //--------------------------------------------------------------

        CHECK_1(
            Write_start,
            1'b0,
            "Writeback does not start in Core_fin cycle"
        );


        @(negedge ACLK);

        Core_fin = 1'b0;


        //--------------------------------------------------------------
        // Next cycle generates Write_start.
        //--------------------------------------------------------------

        @(posedge ACLK);

        #1;


        CHECK_1(
            Write_start,
            1'b1,
            "Write_start generated after output preparation"
        );


        //--------------------------------------------------------------
        // One-cycle pulse.
        //--------------------------------------------------------------

        @(posedge ACLK);

        #1;


        CHECK_1(
            Write_start,
            1'b0,
            "Write_start is one-cycle pulse"
        );


        //==============================================================
        // TEST 9: FAKE MEMORY WRITEBACK
        //==============================================================

        $display("");
        $display("================================================");
        $display("TEST 9: MEMORY WRITEBACK COMPLETION");
        $display("================================================");


        //--------------------------------------------------------------
        // Pretend AXI4 writer needs 5 cycles.
        //--------------------------------------------------------------

        repeat(5)
            @(posedge ACLK);


        @(negedge ACLK);

        Write_done = 1'b1;


        @(posedge ACLK);

        #1;


        CHECK_1(
            Busy,
            1'b0,
            "Busy clears after complete writeback"
        );


        CHECK_1(
            Done,
            1'b1,
            "Done asserted after complete writeback"
        );


        @(negedge ACLK);

        Write_done = 1'b0;


        //==============================================================
        // TEST 10: SOFTWARE READS DONE THROUGH AXI
        //==============================================================

        $display("");
        $display("================================================");
        $display("TEST 10: READ DONE STATUS THROUGH AXI");
        $display("================================================");


        //--------------------------------------------------------------
        // STATUS:
        //
        // Error = 0
        // Done  = 1
        // Busy  = 0
        //
        // binary:
        //
        //      010
        //
        // = 0x2
        //--------------------------------------------------------------

        AXI_READ(
            ADDR_STATUS,
            read_value
        );


        CHECK_32(
            read_value,
            32'h0000_0002,
            "Software sees DONE through STATUS"
        );


        //==============================================================
        // TEST 11: DONE REMAINS STICKY
        //==============================================================

        $display("");
        $display("================================================");
        $display("TEST 11: DONE STICKY THROUGH AXI");
        $display("================================================");


        //--------------------------------------------------------------
        // Wait several cycles.
        //--------------------------------------------------------------

        repeat(4)
            @(posedge ACLK);


        //--------------------------------------------------------------
        // Read STATUS again.
        //--------------------------------------------------------------

        AXI_READ(
            ADDR_STATUS,
            read_value
        );


        CHECK_32(
            read_value,
            32'h0000_0002,
            "DONE remains visible to software"
        );


        //==============================================================
        // TEST 12: SECOND COMMAND USES NEW CONFIGURATION
        //==============================================================

        $display("");
        $display("================================================");
        $display("TEST 12: SECOND AXI START");
        $display("================================================");


        //--------------------------------------------------------------
        // During the previous Busy period CPU already programmed:
        //
        //      SRC_ADDR = DEADBEEF
        //      DST_ADDR = CAFEBABE
        //      MODE     = 0
        //
        // Start a new operation:
        //
        //      START = 1
        //      MODE  = 0
        //
        // CONTROL = 0x1
        //--------------------------------------------------------------

        AXI_WRITE(
            ADDR_CONTROL,
            32'h0000_0001
        );


        //--------------------------------------------------------------
        // The new START should:
        //
        //      clear old Done
        //      set Busy
        //      latch the NEW configuration
        //--------------------------------------------------------------

        CHECK_1(
            Busy,
            1'b1,
            "Second command sets Busy"
        );


        CHECK_1(
            Done,
            1'b0,
            "Second command clears previous Done"
        );


        CHECK_1(
            Mode_latched,
            1'b0,
            "Second command captures new Mode"
        );


        CHECK_32(
            Src_addr_latched,
            32'hDEAD_BEEF,
            "Second command captures new source"
        );


        CHECK_32(
            Dst_addr_latched,
            32'hCAFE_BABE,
            "Second command captures new destination"
        );


        CHECK_1(
            Load_start,
            1'b1,
            "Second command starts loader"
        );


        //==============================================================
        // TEST 13: STATUS FOR SECOND COMMAND
        //==============================================================

        $display("");
        $display("================================================");
        $display("TEST 13: SECOND COMMAND STATUS");
        $display("================================================");


        AXI_READ(
            ADDR_STATUS,
            read_value
        );


        CHECK_32(
            read_value,
            32'h0000_0001,
            "Second command reports BUSY"
        );


        //==============================================================
        // FINAL RESET
        //==============================================================

        @(negedge ACLK);

        ARESETn = 1'b0;

        #1;


        CHECK_1(
            Busy,
            1'b0,
            "Final reset clears Busy"
        );


        CHECK_1(
            Done,
            1'b0,
            "Final reset clears Done"
        );


        //==============================================================
        // TEST SUMMARY
        //==============================================================

        $display("");
        $display("================================================");
        $display("TEST SUMMARY");
        $display("================================================");

        $display(
            "Checks : %0d",
            test_count
        );

        $display(
            "Errors : %0d",
            error_count
        );


        if(error_count == 0) begin

            $display("");
            $display("====================================================");
            $display("ALL NTT CONTROL INTEGRATION TESTS PASSED");
            $display("====================================================");

        end
        else begin

            $display("");
            $display("====================================================");
            $display("NTT CONTROL INTEGRATION TEST FAILED");
            $display("====================================================");

        end


        #20;

        $finish;

    end

endmodule
